package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("recommendations") public class Recommendation{public enum Type{FLIGHT,HOTEL,DESTINATION}public enum Feedback{HELPFUL,NOT_HELPFUL,NOT_INTERESTED}@Id private String id;@Indexed private String userId;private Type recommendationType;@Indexed private String targetId;private String title;private String reason;private double score;private Feedback feedback;private Instant createdAt=Instant.now();public String getId(){return id;}public String getUserId(){return userId;}public void setUserId(String x){userId=x;}public Type getRecommendationType(){return recommendationType;}public void setRecommendationType(Type x){recommendationType=x;}public String getTargetId(){return targetId;}public void setTargetId(String x){targetId=x;}public String getTitle(){return title;}public void setTitle(String x){title=x;}public String getReason(){return reason;}public void setReason(String x){reason=x;}public double getScore(){return score;}public void setScore(double x){score=x;}public Feedback getFeedback(){return feedback;}public void setFeedback(Feedback x){feedback=x;}public Instant getCreatedAt(){return createdAt;}}
